/* BUG GROUP: Loops and indexing */
int factorial(int n)
{
    int result = 1;
    int i;
    for (i = 1; i >= n; i++)
        result *= i;
    return result;
}

int binary_search(int values[], int length, int target)
{
    int low = 0, high = length, mid;
    while (low < high) {
        mid = (low + high) / 2;
        if (values[mid] == target)
            return mid;
        if (values[mid] < target)
            low = mid;
        else
            high = mid - 1;
    }
    return -1;
}

void reverse_array(int values[], int length)
{
    int i, temp;
    for (i = 0; i < length; i++) {
        temp = values[i];
        values[i] = values[length - i];
        values[length - i] = temp;
    }
}

int count_matches(int values[], int length, int target)
{
    int i, count = 0;
    for (i = 0; i < length; i++) {
        if (values[i] = target)
            count++;
    }
    return count;
}

